Q=[
make(1,"You meet your host family for the first time at 7 p.m. Which greeting is most appropriate?",{"A":"Good evening. It is nice to meet you.","B":"Good night. Wake me up now.","C":"See you yesterday.","D":"Give me your room."},"A","At a first meeting in the evening, Good evening and It is nice to meet you are polite and appropriate.","Use both the time of day and the relationship, a first meeting, to select the greeting.",["Identify the time: 7 p.m.","Identify the social situation: meeting the host family for the first time.","Choose an evening greeting and a first-meeting courtesy.","Reject goodbye, impossible time wording, and demanding language.","Select A because it fits both context clues."],"easy"),
make(2,"You accidentally step on a classmate's foot. What should you say first?",{"A":"I'm sorry. Are you okay?","B":"Congratulations on your foot.","C":"Please sell me a ticket.","D":"Good luck with yesterday."},"A","An accidental injury calls for an apology and concern, which are both expressed in A.","Match the social problem, an accidental hurt, with an apology followed by care for the person.",["Identify what happened: you caused accidental discomfort.","Find a phrase that apologizes.","Find a follow-up showing concern.","Reject congratulations, shopping, and unrelated time phrases.","Choose A because it repairs the interaction politely."],"easy"),
make(3,"A friend lends you a charger when your phone is almost out of power. Which response is best?",{"A":"Thanks a lot; that really helps.","B":"I refuse to thank you.","C":"Where is the nearest airport?","D":"The charger is a birthday cake."},"A","A friend has helped you, so expressing thanks and the benefit is appropriate.","Identify the helpful action and choose a response that acknowledges it.",["Notice the friend lends a charger.","Recognize that you received help.","Match help with a thankful expression.","Remove refusal, travel, and nonsensical object statements.","Select A because it shows sincere gratitude."],"easy"),
make(4,"You want to ask a friend to join your study group on Saturday. Which invitation is most natural?",{"A":"Would you like to study with us on Saturday?","B":"You must disappear on Saturday.","C":"Please apologize to the dictionary.","D":"I congratulate your homework."},"A","Would you like to ... is a polite invitation, and the activity and day are clearly stated.","Use the intended action, inviting someone, and check whether the sentence leaves the friend a choice.",["Identify the goal: add a friend to a study group.","Find an expression that invites rather than commands.","Check that the activity and Saturday are included.","Reject threatening and nonsensical choices.","Choose A because it is clear and polite."],"easy"),
make(5,"At a crowded bus stop, you need to pass to reach your younger sister. What should you say?",{"A":"Excuse me, may I get through?","B":"Move or I will shout at everyone.","C":"Congratulations, bus stop.","D":"I am buying the sidewalk."},"A","Excuse me and may I get through? politely ask others for space without threatening them.","Consider the public setting and choose a request that respects other people's space.",["Identify the need: pass through a crowd.","Use Excuse me to get attention politely.","Use may I to ask permission for space.","Reject threats and statements unrelated to passing.","Select A because it is respectful and functional."],"easy"),
make(6,"You are lost near a train station and need help. Which sentence should you use?",{"A":"Could you tell me how to get to the station?","B":"I am sorry your train won.","C":"Please congratulate my map.","D":"The station is a delicious color."},"A","The sentence politely asks for directions to the station, which is the needed help.","Match being lost with a location question that requests directions politely.",["Identify the problem: you do not know the way.","Identify the destination: the station.","Choose a polite direction request.","Reject apology, congratulations, and nonsensical descriptions.","Choose A because it asks for exactly the missing information."],"medium"),
make(7,"At a shop, the shirt is too expensive for you. Which response politely refuses it?",{"A":"No, thank you. It is more than I can spend.","B":"Yes, give me every shirt.","C":"Good evening, I broke the window.","D":"Please lend me the cashier's name."},"A","No, thank you politely refuses, and the second sentence gives a respectful reason about price.","Look for a refusal that keeps polite language and connects to the stated cost problem.",["Identify the problem: the shirt costs too much.","Find a phrase that declines the purchase.","Check for polite language such as No, thank you.","Reject acceptance, unrelated damage, and a name request.","Select A because it refuses without insulting the seller."],"medium"),
make(8,"Your teammate wins the school speech contest. What should you say?",{"A":"Congratulations! You worked hard.","B":"I'm sorry you won.","C":"Please return the trophy to yesterday.","D":"Could you apologize to the judge?"},"A","Winning a contest is a success, so Congratulations with praise is the appropriate response.","Match the event, a successful achievement, with a celebratory expression.",["Identify the event: the teammate won.","Classify it as a success rather than a loss.","Choose the conventional congratulatory phrase.","Reject apology and impossible or negative responses.","Select A because it celebrates the achievement sincerely."],"easy"),
make(9,"A neighbor is carrying several heavy boxes. You want to offer help. Which sentence is best?",{"A":"Would you like some help with those boxes?","B":"You should carry more boxes alone.","C":"I congratulate your heavy shoes.","D":"Why did the boxes learn English?"},"A","Would you like some help? politely offers assistance and those boxes identifies the task.","Use the visible difficulty and choose an offer rather than an order or joke.",["Observe the neighbor carrying heavy boxes.","Infer that carrying them may be difficult.","Find the option that offers help with a question.","Reject commands and unrelated or absurd statements.","Choose A because it gives the neighbor a respectful choice."],"medium"),
make(10,"You cannot attend a friend's birthday dinner because of a family event. Which reply is most considerate?",{"A":"I'm sorry I can't come, but I hope you have a wonderful birthday.","B":"Your birthday is canceled because I am busy.","C":"I will arrive yesterday and leave the cake.","D":"Congratulations on my family event."},"A","A apologizes, gives a truthful limitation, and still wishes the friend well; it is considerate and complete.","Combine the need to decline with the relationship-preserving elements of apology and good wishes.",["Identify the conflict: a family event prevents attendance.","Find an apology for not coming.","Check that the reply offers a kind birthday wish.","Reject rude, impossible-time, and self-focused alternatives.","Select A because it declines while preserving the friendship."],"hard"),
]
